275	#pragma warning restore CA1862 // Use the 'StringComparison' method overloads to perform case-insensitive string comparisons
276	
277	                newUser = await CreateUserInternalAsync(name, dbContext).ConfigureAwait(false);
278	
279	                dbContext.Users.Add(newUser);
