895	                string username,
896	                string password,
897	                User? user)
898	        {
899	            bool success = false;
900	            IAuthenticationProvider? authenticationProvider = null;
901	
902	            foreach (var provider in GetAuthenticationProviders(user))
903	            {
904	                var providerAuthResult =
905	                    await AuthenticateWithProvider(provider, username, password, user).ConfigureAwait(false);
906	                var updatedUsername = providerAuthResult.Username;
907	                success = providerAuthResult.Success;
