        /// </summary>
        /// <param name="disposing">Defines if the class has been cleaned up by a dispose or finalizer.</param>
        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                _userLock.Dispose();
            }
        }
    }
